func merge(chs ...<-chan int) <-chan int {
    out := make(chan int)
    var wg sync.WaitGroup
    for _, c := range chs {
        wg.Add(1)
        go func(c <-chan int){ defer wg.Done(); for v := range c { out <- v } }(c)
    }
    go func(){ wg.Wait(); close(out) }()
    return out
}

